Here's a `humanize_delta` implementation that handles both past and future deltas, with special cases like "just now" and "yesterday", plus pytest tests.

```python
# file: solution.py
from datetime import datetime


def _fmt(count: int, unit: str) -> str:
    return f"{count} {unit}{'s' if count != 1 else ''}"


def humanize_delta(then: datetime, now: datetime) -> str:
    """Return a human-readable description of the difference between two datetimes.

    Examples: 'just now', '5 minutes ago', 'in 3 hours', 'yesterday',
    '2 days ago', 'in 1 month', 'a year ago'.
    """
    if then.tzinfo is None and now.tzinfo is not None:
        now = now.replace(tzinfo=None)
    elif then.tzinfo is not None and now.tzinfo is None:
        then = then.replace(tzinfo=None)

    delta = now - then
    seconds = delta.total_seconds()
    future = seconds < 0
    seconds = abs(seconds)

    # Seconds
    if seconds < 10:
        return "just now"
    if seconds < 60:
        text = _fmt(int(seconds), "second")

    # Minutes / hours
    elif seconds < 3600:
        text = _fmt(int(seconds // 60), "minute")
    elif seconds < 86400:
        text = _fmt(int(seconds // 3600), "hour")

    # Days
    elif seconds < 86400 * 30:
        days = int(seconds // 86400)
        if future and days == 1:
            return "tomorrow"
        if not future and days == 1:
            return "yesterday"
        text = _fmt(days, "day")

    # Months
    elif seconds < 86400 * 365:
        months = int(seconds // (86400 * 30))
        text = _fmt(months, "month")

    # Years
    else:
        years = int(seconds // (86400 * 365))
        if years == 1:
            text = "a year"
        else:
            text = _fmt(years, "year")

    return f"in {text}" if future else f"{text} ago"
```

