Here's a practical email validator with a focused regex plus length checks, and a pytest suite to go with it.

```python
# file: solution.py
import re

_LABEL_RE = re.compile(r"^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$")


def is_valid_email(addr: str) -> bool:
    """Return True if *addr* satisfies practical signup-form email rules.

    Rules enforced:
    - exactly one '@' separating local part and domain
    - non-empty local part, at most 64 characters
    - domain has at least one dot, valid label characters,
      and no leading/trailing or consecutive dots
    """
    if not isinstance(addr, str) or not addr:
        return False

    if addr.count("@") != 1:
        return False

    local, _, domain = addr.partition("@")

    if not local or len(local) > 64:
        return False

    if domain.startswith(".") or domain.endswith(".") or ".." in domain:
        return False

    labels = domain.split(".")
    if len(labels) < 2:
        return False

    return all(_LABEL_RE.match(label) for label in labels)
```

