This implementation buckets each invoice by days past due relative to `as_of`, supporting both `date` objects and ISO date strings.

```python
# file: solution.py
from datetime import date, datetime

def _to_date(d):
    if isinstance(d, datetime):
        return d.date()
    if isinstance(d, date):
        return d
    return date.fromisoformat(str(d))

def age_receivables(invoices, as_of):
    """Bucket invoice balances into aging buckets by days past due.

    Buckets: 'current' (not yet due), '1-30', '31-60', '61-90', '90+'.
    Returns dict of bucket -> total balance.
    """
    buckets = {"current": 0.0, "1-30": 0.0, "31-60": 0.0, "61-90": 0.0, "90+": 0.0}
    as_of = _to_date(as_of)
    for invoice_id, due_date, balance in invoices:
        days_overdue = (as_of - _to_date(due_date)).days
        if days_overdue <= 0:
            bucket = "current"
        elif days_overdue <= 30:
            bucket = "1-30"
        elif days_overdue <= 60:
            bucket = "31-60"
        elif days_overdue <= 90:
            bucket = "61-90"
        else:
            bucket = "90+"
        buckets[bucket] += balance
    return buckets
```

