Here's an implementation with a small state-machine-free approach: strip lines, skip blanks/comments, and detect quoted values so quoted content is preserved verbatim.

```python
# file: solution.py
def parse_config(text: str) -> dict[str, str]:
    config: dict[str, str] = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if '=' not in stripped:
            raise ValueError(f"Invalid config line: {line!r}")
        key, _, value = stripped.partition('=')
        key = key.strip()
        if not key:
            raise ValueError(f"Missing key in line: {line!r}")
        value = value.strip()
        if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
            # Remove surrounding quotes; content preserved verbatim.
            value = value[1:-1]
        else:
            # Unquoted: strip inline comments and whitespace.
            if '#' in value:
                value = value.split('#', 1)[0].strip()
        config[key] = value
    return config
```

