Here's a straightforward implementation that counts weekdays (Mon–Fri) in the inclusive range, minus any holidays falling on weekdays within the range.

```python
# file: solution.py
from datetime import date, timedelta


def business_days_between(start: date, end: date, holidays: set[date] | None = None) -> int:
    """Count weekdays (Mon-Fri) between start and end, inclusive, excluding holidays."""
    if start > end:
        raise ValueError("start date must not be after end date")
    holidays = holidays or set()

    count = 0
    current = start
    one_day = timedelta(days=1)
    while current <= end:
        if current.weekday() < 5 and current not in holidays:
            count += 1
        current += one_day
    return count
```

