    if lowered in _TRUE_VALUES:
        return True
    if lowered in _FALSE_VALUES:
        return False
    raise ValueError(f"invalid boolean value for {name!r}: {raw!r}")


def load_env(spec: dict[str, type], env: Mapping[str, str] | None = None) -> dict:
    """Read variables from ``env`` (defaults to ``os.environ``) and coerce each
    value to the type named in ``spec``.

    Supported types are ``int``, ``float``, ``bool`` and ``str``. If any keys
    listed in ``spec`` are missing, a single :class:`MissingEnvError` is
    raised naming all of them at once.
    """
    source = os.environ if env is None else env
    missing = [name for name in spec if name not in source]
    if missing:
        raise MissingEnvError(missing)

    result: dict = {}
    for name, expected in spec.items():
        raw = source[name]
        if expected is bool:
            result[name] = _coerce_bool(name, raw)
        elif expected is str:
            result[name] = raw
        else:
            result[name] = expected(raw)
    return result
