def overlap(a_start: datetime, a_end: datetime,
            b_start: datetime, b_end: datetime) -> timedelta:
    """Return the duration that two time intervals overlap (zero if none)."""
    start = max(a_start, b_start)
    end = min(a_end, b_end)
    if end <= start:
        return timedelta(0)
    return end - start
