`Inventory` tracks on-hand and reserved units per SKU; reservations reduce availability, releases undo reservations, and commits permanently remove reserved stock.

```python
# file: solution.py
class OutOfStockError(Exception):
    """Raised when a request exceeds available (unreserved) stock."""


class Inventory:
    def __init__(self):
        self._on_hand = {}    # sku -> total units physically held
        self._reserved = {}   # sku -> units currently reserved

    def add_stock(self, sku, qty):
        if qty < 0:
            raise ValueError("qty must be non-negative")
        self._on_hand[sku] = self._on_hand.get(sku, 0) + qty

    def available(self, sku):
        return self._on_hand.get(sku, 0) - self._reserved.get(sku, 0)

    def reserve(self, sku, qty):
        if qty < 0:
            raise ValueError("qty must be non-negative")
        if self.available(sku) < qty:
            raise OutOfStockError(
                f"cannot reserve {qty} of {sku!r}, only {self.available(sku)} available"
            )
        self._reserved[sku] = self._reserved.get(sku, 0) + qty

    def release(self, sku, qty):
        if qty < 0:
            raise ValueError("qty must be non-negative")
        if self._reserved.get(sku, 0) < qty:
            raise OutOfStockError(
                f"cannot release {qty} of {sku!r}, only {self._reserved.get(sku, 0)} reserved"
            )
        self._reserved[sku] -= qty
        if self._reserved[sku] == 0:
            del self._reserved[sku]

    def commit(self, sku, qty):
        """Remove committed units from both reserved and on-hand stock."""
        if qty < 0:
            raise ValueError("qty must be non-negative")
        if self._reserved.get(sku, 0) < qty:
            raise OutOfStockError(
                f"cannot commit {qty} of {sku!r}, only {self._reserved.get(sku, 0)} reserved"
            )
        self._reserved[sku] -= qty
        if self._reserved[sku] == 0:
            del self._reserved[sku]
        self._on_hand[sku] -= qty
```

