```python
# file: solution.py
from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Optional

_SEMVER_RE = re.compile(
    r"^v?(?P<major>\d+)\.(?P<minor>\d+)\.(?P<patch>\d+)"
    r"(?:-(?P<prerelease>[0-9A-Za-z.-]+))?"
    r"(?:\+(?P<build>[0-9A-Za-z.-]+))?$"
)


@dataclass(frozen=True)
class Version:
    """A semantic version with optional pre-release and build metadata."""

    major: int
    minor: int
    patch: int
    prerelease: Optional[str] = None
    build: Optional[str] = None

    def __post_init__(self) -> None:
        for name in ("major", "minor", "patch"):
            if getattr(self, name) < 0:
                raise ValueError(f"{name} must be non-negative")

    @classmethod
    def parse(cls, text: str) -> "Version":
        """Parse a version string like '1.2.3', 'v2.0.0', or '1.2.3-beta.1'."""
        if not isinstance(text, str):
            raise TypeError("version must be a string")
        match = _SEMVER_RE.match(text.strip())
        if match is None:
            raise ValueError(f"invalid version string: {text!r}")
        return cls(
            major=int(match.group("major")),
            minor=int(match.group("minor")),
            patch=int(match.group("patch")),
            prerelease=match.group("prerelease"),
            build=match.group("build"),
        )

    def _core(self) -> tuple[int, int, int]:
        return (self.major, self.minor, self.patch)

    @staticmethod
    def _prerelease_key(pre: Optional[str]) -> tuple:
        # A release sorts after any pre-release of the same core version.
        if pre is None:
            return (1,)
        parts = []
        for ident in pre.split("."):
            if ident.isdigit():
                parts.append((0, int(ident), ""))
            else:
                parts.append((1, 0, ident))
        return (0, parts)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._core() == other._core() and self.prerelease == other.prerelease

    def __lt__(self, other: "Version") -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        if self._core() != other._core():
            return self._core() < other._core()
        return self._prerelease_key(self.prerelease) < self._prerelease_key(other.prerelease)

    def __gt__(self, other: "Version") -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return other < self

    def __hash__(self) -> int:
        return hash((self._core(), self.prerelease))

    def __repr__(self) -> str:
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += f"-{self.prerelease}"
        if self.build:
            text += f"+{self.build}"
        return f"Version({text!r})"
