    # Should interleave, e.g. a b a a (or similar), not "a a a b"
    picks = cycle(rr, 4)
    assert not any(
        picks[i : i + 3] == ["a", "a", "a"] for i in range(len(picks) - 2)
    )
    assert Counter(picks) == {"a": 3, "b": 1}


def test_smooth_order_classic():
