```python
# file: solution.py
import re

_INT_RE = re.compile(r'^[+-]?\d+$')
_FLOAT_RE = re.compile(r'^[+-]?(\d+\.\d*|\.\d+)([eE][+-]?\d+)?$')


def _coerce(value):
    if value == '':
        return None
    if value.lower() == 'true':
        return True
    if value.lower() == 'false':
        return False
    if _INT_RE.match(value):
        return int(value)
    if _FLOAT_RE.match(value) or re.match(r'^[+-]?(\d+)([eE][+-]?\d+)$', value):
        return float(value)
    return value


def coerce_row(row: dict) -> dict:
    return {key: _coerce(value) for key, value in row.items()}
