import pytest

from solution import check_schema


def _reference_errors(data: Any, schema: Any) -> list[str]:
    """Independent traversal used to derive the expected error strings."""
    out: list[str] = []

    def walk(node: Any, sch: Any, path: str) -> None:
        if isinstance(sch, type):
            if not isinstance(node, sch):
                out.append(f"{path}: expected {sch.__name__}, got {type(node).__name__}")
        elif isinstance(sch, dict):
            if isinstance(node, dict):
                for key, sub in sch.items():
                    if key in node:
                        walk(node[key], sub, f"{path}.{key}" if path else key)
        elif isinstance(sch, list):
            if isinstance(node, list):
                for i, item in enumerate(node):
                    walk(item, sch[0], f"{path}[{i}]" if path else f"[{i}]")

    walk(data, schema, "$")
    return out


