# file: solution.py
from __future__ import annotations

_TRUE_STRINGS = {"true"}
_FALSE_STRINGS = {"false"}


def _coerce_value(value: str) -> object:
    """Convert a single string cell to its most likely native type."""
    if value == "":
        return None
    lowered = value.strip().lower()
    if lowered in _TRUE_STRINGS:
        return True
    if lowered in _FALSE_STRINGS:
        return False
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value


def coerce_row(row: dict) -> dict:
    """Coerce every value in a CSV row to int, float, bool, or None where applicable.

    Values that do not match any recognized pattern are returned unchanged.
    A new dict is returned; the input row is not mutated.
    """
    return {key: _coerce_value(value) for key, value in row.items()}
