def reorder_report(stock, rules):
    """Return [(sku, qty_to_order)] for SKUs at/below reorder point, sorted by sku."""
    report = []
    for sku in sorted(stock):
        if sku not in rules:
            continue
        rule = rules[sku]
        reorder_point = rule["reorder_point"]
        order_up_to = rule["order_up_to"]
        on_hand = stock[sku]
        if on_hand <= reorder_point:
            qty = max(order_up_to - on_hand, 0)
            report.append((sku, qty))
    return report
