Here's a `LengthConverter` class that converts between units via their meters-per-unit factors, with a pytest suite covering conversions, round-trips, and error handling.

```python
# file: solution.py


class UnknownUnitError(ValueError):
    """Raised when a unit is not supported by the converter."""


class LengthConverter:
    """Converts length values between units using meters as the base."""

    METERS_PER_UNIT = {
        "mm": 0.001,
        "cm": 0.01,
        "m": 1.0,
        "km": 1000.0,
        "in": 0.0254,
        "ft": 0.3048,
        "yd": 0.9144,
        "mi": 1609.344,
    }

    def convert(self, value, from_unit, to_unit):
        """Convert `value` from `from_unit` to `to_unit`.

        Units are case-sensitive: "cm" works, "CM" does not.
        """
        try:
            from_factor = self.METERS_PER_UNIT[from_unit]
            to_factor = self.METERS_PER_UNIT[to_unit]
        except KeyError as exc:
            raise UnknownUnitError(
                f"unsupported unit: {exc.args[0]!r}; "
                f"expected one of {sorted(self.METERS_PER_UNIT)}"
            ) from None
        return value * from_factor / to_factor
```

