Here's a smooth weighted round-robin implementation using the interleaved (/nginx-style) current-weight algorithm, plus its test suite.

```python
# file: solution.py
from typing import Dict


class WeightedRoundRobin:
    """Interleaved weighted round-robin scheduler.

    Given ``{name: weight}``, :meth:`next` returns backend names such that
    over one full cycle of ``sum(weights)`` picks, each backend is chosen
    exactly ``weight`` times, spread evenly through the cycle rather than
    clustered into bursts.
    """

    def __init__(self, backends: Dict[str, int]) -> None:
        if not backends:
            raise ValueError("at least one backend is required")
        for name, weight in backends.items():
            if not isinstance(weight, int) or weight <= 0:
                raise ValueError(f"weight for {name!r} must be a positive int")
        self._backends = dict(backends)
        self._current = {name: 0 for name in backends}
        self._total = sum(backends.values())

    def next(self) -> str:
        """Return the next backend name, advancing the cycle."""
        for name in self._backends:
            self._current[name] += self._backends[name]
        chosen = max(self._current, key=self._current.get)
        self._current[chosen] -= self._total
        return chosen
```

```python
# file: test_solution.py
import pytest

from solution import WeightedRoundRobin


def take(wrr, n):
    return [wrr.next() for _ in range(n)]


@pytest.mark.parametrize(
    "backends",
    [
        {"a": 5},
        {"a": 3, "b": 1},
        {"api": 2, "img": 3, "static": 7},
        {"x": 1, "y": 1, "z": 1},
    ],
)
def test_cycle_length_matches_total_weight(backends):
    wrr = WeightedRoundRobin(backends)
    picks = take(wrr, sum(backends.values()))
    assert len(picks) == sum(backends.values())


@pytest.mark.parametrize(
    "backends",
    [
        {"a": 3, "b": 1},
        {"a": 2, "b": 2},
        {"alpha": 1, "beta": 4, "gamma": 2},
    ],
)
def test_only_known_backends_returned(backends):
    wrr = WeightedRoundRobin(backends)
    picks = take(wrr, sum(backends.values()) * 3)
    assert set(picks) <= set(backends)


@pytest.mark.parametrize(
    "backends",
    [
        {"a": 3, "b": 2},
        {"a": 1, "b": 1, "c": 1},
        {"primary": 6, "shadow": 1},
    ],
)
def test_two_instances_agree(backends):
    wrr_a = WeightedRoundRobin(backends)
    wrr_b = WeightedRoundRobin(backends)
    n = sum(backends.values())
    assert take(wrr_a, n) == take(wrr_b, n)


def test_counts_are_stable_across_cycles():
    backends = {"a": 3, "b": 2, "c": 1}
    wrr = WeightedRoundRobin(backends)
    cycle_len = sum(backends.values())
    first = take(wrr, cycle_len)
    second = take(wrr, cycle_len)
    from collections import Counter
    assert Counter(first) == Counter(second)


def test_picks_are_strings():
