    assert all(isinstance(p, str) for p in take(wrr, 6))


@pytest.mark.parametrize("name,weight", [("solo", 1), ("only", 10), ("b", 3)])
def test_single_backend_always_wins(name, weight):
    wrr = WeightedRoundRobin({name: weight})
    assert set(take(wrr, weight * 2)) == {name}


@pytest.mark.parametrize(
    "backends",
    [
        {"a": 1, "b": 1},
        {"p": 1, "q": 1, "r": 1},
    ],
)
def test_equal_weights_all_participate(backends):
    wrr = WeightedRoundRobin(backends)
    picks = take(wrr, sum(backends.values()))
    assert set(picks) == set(backends)


def test_gaps_never_exceed_cycle_length():
    backends = {"a": 4, "b": 1, "c": 2}
    wrr = WeightedRoundRobin(backends)
    cycle = take(wrr, sum(backends.values()))
    last_index = {}
    for i, name in enumerate(cycle):
        if name in last_index:
            assert i - last_index[name] <= len(cycle)
        last_index[name] = i
